DROP VIEW "books"."subscriptions";--> statement-breakpoint
ALTER TABLE "books"."bills" DROP CONSTRAINT "ck_bills_review";--> statement-breakpoint
ALTER TABLE "books"."bills" ADD CONSTRAINT "ck_bills_review" CHECK (("review")::text = ANY ((ARRAY['ok'::character varying, 'needs_review'::character varying, 'accepted'::character varying, 'personal'::character varying, 'void'::character varying])::text[]));--> statement-breakpoint
CREATE VIEW "books"."subscriptions" AS (SELECT DISTINCT ON (c.vendor_id, (lower(COALESCE(c.plan, ''::text)))) c.vendor_id, c.vendor, c.vendor_name, c.plan, c.cycle, c.currency, c.total_cents AS last_total_cents, c.cad_cents AS last_cad_cents, c.issued_on AS last_billed_on, (c.issued_on + CASE WHEN c.cycle::text = 'yearly'::text THEN '1 year'::interval ELSE '1 mon'::interval END)::date AS renews_on, CASE WHEN c.cycle::text = 'yearly'::text THEN round(c.cad_cents::numeric / 12.0)::bigint ELSE c.cad_cents END AS monthly_cad_cents, (SELECT min(b2.issued_on) FROM books.bills b2 WHERE b2.vendor_id = c.vendor_id AND lower(COALESCE(b2.plan, ''::text)) = lower(COALESCE(c.plan, ''::text)) AND (b2.review::text <> ALL (ARRAY['personal'::character varying, 'void'::character varying]::text[]))) AS since, (SELECT count(*)::integer FROM books.bills b2 WHERE b2.vendor_id = c.vendor_id AND lower(COALESCE(b2.plan, ''::text)) = lower(COALESCE(c.plan, ''::text)) AND (b2.review::text <> ALL (ARRAY['personal'::character varying, 'void'::character varying]::text[]))) AS bills FROM books.bill_costs c WHERE (c.cycle::text = ANY (ARRAY['monthly'::character varying, 'yearly'::character varying]::text[])) AND (c.review::text <> ALL (ARRAY['personal'::character varying, 'void'::character varying]::text[])) ORDER BY c.vendor_id, (lower(COALESCE(c.plan, ''::text))), c.issued_on DESC, c.bill_id DESC);